/* door.c: ask the kernel for two things an ordinary user may not have */
#include <errno.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

int main(void) {
    printf("uid=%d euid=%d\n", getuid(), geteuid());
    int fd = open("/etc/master.passwd", O_RDONLY);   /* root-only file on macOS */
    printf("open: %d (%s)\n", fd, fd < 0 ? strerror(errno) : "ok");
    int r = setuid(0);                               /* ask to become root */
    printf("setuid(0): %d (%s)\n", r, r < 0 ? strerror(errno) : "ok");
    return 0;
}

