struct sock_filter filter[] = {
    /* [0] load the architecture */
    BPF_STMT(BPF_LD | BPF_W | BPF_ABS,
             offsetof(struct seccomp_data, arch)),
    /* [1] wrong architecture: jump to [7] */
    BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, t_arch, 0, 5),
    /* [2] load the system call number */
    BPF_STMT(BPF_LD | BPF_W | BPF_ABS,
             offsetof(struct seccomp_data, nr)),
    /* [3] x32 numbers (bit 30 set): jump to [7] */
    BPF_JUMP(BPF_JMP | BPF_JGT | BPF_K, upper_nr_limit, 3, 0),
    /* [4] not the blocked call: jump to [6] */
    BPF_JUMP(BPF_JMP | BPF_JEQ | BPF_K, syscall_nr, 0, 1),
    /* [5] the blocked call: fail with errno */
    BPF_STMT(BPF_RET | BPF_K,
             SECCOMP_RET_ERRNO | (f_errno & SECCOMP_RET_DATA)),
    /* [6] everything else: allow */
    BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_ALLOW),
    /* [7] wrong architecture: kill */
    BPF_STMT(BPF_RET | BPF_K, SECCOMP_RET_KILL_PROCESS),
};

/* allow-list with libseccomp (Linux only): kill on anything not listed */
#include <seccomp.h>
#include <sys/prctl.h>

int lock_down(void)
{
    if (prctl(PR_SET_NO_NEW_PRIVS, 1, 0, 0, 0) != 0) return -1;
    scmp_filter_ctx ctx = seccomp_init(SCMP_ACT_KILL_PROCESS);
    if (ctx == NULL) return -1;
    int rc = 0;
    rc |= seccomp_rule_add(ctx, SCMP_ACT_ALLOW, SCMP_SYS(read), 0);
    rc |= seccomp_rule_add(ctx, SCMP_ACT_ALLOW, SCMP_SYS(write), 1,
                           SCMP_A0(SCMP_CMP_EQ, 1));      /* stdout only */
    rc |= seccomp_rule_add(ctx, SCMP_ACT_ALLOW, SCMP_SYS(exit_group), 0);
    if (rc == 0) rc = seccomp_load(ctx);                   /* now enforced */
    seccomp_release(ctx);
    return rc;
}

