/* ... join container namespaces, pivot_root into the image ... */
chdir(cfg->cwd);            /* "/proc/self/fd/7/" resolves to a host directory */
execve(cfg->argv[0], cfg->argv, cfg->envp);

/* FIXED, following the runc 1.1.12 advisory */
int cg = open("/sys/fs/cgroup", O_RDONLY | O_DIRECTORY | O_CLOEXEC);
/* ... join namespaces, pivot_root ... */
if (chdir(cfg->cwd) != 0) die("chdir");
if (getcwd(buf, sizeof buf) == NULL && errno == ENOENT)
    die("working directory is outside the container");    /* Linux reports ENOENT */
close_range(3, ~0U, CLOSE_RANGE_CLOEXEC);  /* every non-stdio fd closes at execve */
execve(cfg->argv[0], cfg->argv, cfg->envp);

/* VULNERABLE: check with the real UID, use with the effective UID (root) */
if (access(path, W_OK) == 0) {                     /* time of check */
    int fd = open(path, O_WRONLY | O_APPEND);      /* time of use: path may differ */
    if (fd >= 0) { write(fd, msg, len); close(fd); }
}

/* FIXED: let the kernel check and open in one step, as the caller */
uid_t euid = geteuid();
if (seteuid(getuid()) != 0) die("seteuid");        /* become the caller */
int fd = open(path, O_WRONLY | O_APPEND | O_NOFOLLOW);
if (seteuid(euid) != 0) die("seteuid back");
if (fd < 0) die("open");                           /* refused: caller may not write */
write(fd, msg, len);
close(fd);

